/* ============================================================
   เตรียมข้อมูลให้ AI
   ------------------------------------------------------------
   1) อ่านข้อความที่ลูกค้าพิมพ์มาจาก LINE
   2) เรียง FAQ ในชีตตามความใกล้เคียงกับคำถาม (ทนคำที่พิมพ์ผิด)
   3) ประกอบคำสั่งให้ AI Agent เอาไปตอบ
   ============================================================ */

/* ===== แก้ข้อมูลบริษัทตรงนี้ได้เลย ===== */
const BUSINESS = `บริษัท ไอว่า ริช ยู ดี จำกัด (IWA Rich U D)
ธุรกิจ: ICT Solutions ครบวงจร และสื่อการเรียนรู้ดิจิทัลมาตรฐาน CEFR สำหรับสถานศึกษา
บริการ: วางระบบเครือข่าย, ห้องเรียนอัจฉริยะ, ห้องแลปภาษา, พัฒนาซอฟต์แวร์/LMS,
        ดูแลรักษาระบบ, จำหน่ายอุปกรณ์และสื่อการเรียนรู้, อบรม ICT และภาษาอังกฤษ CEFR
โทร: 099-626-9787, 082-731-8082
อีเมล: supannee@iwarichyoudee.com
ที่อยู่: 222/56 หมู่ 7 ต.นิมิตรราช อ.บางบัวทอง จ.นนทบุรี 11110`;

const HONORIFIC = 'ครับ';   // เปลี่ยนเป็น 'ค่ะ' ได้
const MAX_ROWS = 100;       // จำนวนแถวจากชีตที่ส่งให้ AI (เรียงเรื่องที่ใกล้เคียงไว้บนสุดก่อนตัด)

/* ===== 1) ข้อความจากลูกค้า ===== */
const body = $('Webhook').first().json.body || {};
const events = (body.events || []).filter(
  (e) => e.type === 'message' && e.message && e.message.type === 'text' && e.message.text
);
if (!events.length) return [];   // ไม่ใช่ข้อความตัวอักษร -> ไม่ต้องตอบ

/* ===== 2) ข้อมูลจากชีต ===== */
const rows = $input.all()
  .map((i) => ({
    keyword: String(i.json.keyword || '').trim(),
    answer: String(i.json.answer || '').trim(),
  }))
  .filter((r) => r.keyword && r.answer);

/* ===== 3) จับคำที่พิมพ์ผิด =====
   ตัดวรรณยุกต์ทิ้ง แล้วยุบตัวอักษรที่เสียงเหมือนกันให้เป็นตัวเดียว
   ราคะ / ร่าคา / ลาคา / ราฆา  ->  ราคา                              */
const SAME = {
  'ข': 'ค', 'ฃ': 'ค', 'ฅ': 'ค', 'ฆ': 'ค', 'ฉ': 'ช', 'ฌ': 'ช',
  'ซ': 'ส', 'ศ': 'ส', 'ษ': 'ส', 'ญ': 'ย', 'ฎ': 'ด', 'ฏ': 'ต',
  'ฐ': 'ท', 'ฑ': 'ท', 'ฒ': 'ท', 'ถ': 'ท', 'ธ': 'ท', 'ณ': 'น',
  'ผ': 'พ', 'ภ': 'พ', 'ฝ': 'ฟ', 'ล': 'ร', 'ฬ': 'ร', 'ฮ': 'ห',
  'ะ': 'า', 'ั': 'า', 'ๅ': 'า', 'ำ': 'า', 'ิ': 'ี', 'ึ': 'ื',
  'ุ': 'ู', 'แ': 'เ', 'โ': 'เ', 'ใ': 'ไ',
};

function fold(s) {
  return String(s || '').toLowerCase().normalize('NFC')
    .replace(/[็-๎]/g, '')              // วรรณยุกต์ ไม้ไต่คู้ ทัณฑฆาต
    .replace(/[^฀-๿a-z0-9]/g, '')       // เหลือเฉพาะตัวอักษร
    .replace(/(.)\1{2,}/g, '$1')                  // ราคาาาา -> ราคา
    .split('').map((c) => SAME[c] || c).join('');
}

function distance(a, b) {
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[b.length];
}

function similar(q, k) {
  if (!q || !k) return 0;
  if (q === k) return 1;
  const long = q.length >= k.length ? q : k;
  const short = q.length >= k.length ? k : q;
  if (short.length >= 2 && long.includes(short)) return 0.95;   // คีย์เวิร์ดอยู่ในประโยค
  return 1 - distance(q, k) / long.length;
}

/* ===== 4) ประกอบคำสั่งให้ AI (ทีละข้อความ) ===== */
return events.map((ev) => {
  const question = ev.message.text.trim();
  const q = fold(question);

  // ให้คะแนนทุกแถว แล้วเรียงเรื่องที่ใกล้เคียงที่สุดไว้บนสุด
  const ranked = rows
    .map((r) => {
      const score = Math.max(
        ...r.keyword.split(/[,|/\n;]+/).map((k) => similar(q, fold(k)))
      );
      return { ...r, score };
    })
    .sort((a, b) => b.score - a.score);

  const faqList = ranked
    .slice(0, MAX_ROWS)
    .map((r, i) => `${i + 1}. [${r.keyword}] ${r.answer}`)
    .join('\n');

  const guesses = ranked
    .filter((r) => r.score >= 0.35)
    .slice(0, 3)
    .map((r) => `"${r.keyword}" (ใกล้เคียง ${Math.round(r.score * 100)}%)`)
    .join(', ') || '(เดาไม่ได้ ให้ตอบจากข้อมูลบริษัท)';

  const systemPrompt = `คุณคือผู้ช่วยตอบแชท LINE OA ของ ${BUSINESS}

ข้อมูลถาม-ตอบที่ทีมงานเตรียมไว้ (เรียงจากที่ใกล้เคียงคำถามนี้มากที่สุด):
${faqList || '(ยังไม่มีข้อมูลในชีต)'}

ลูกค้าพิมพ์มาว่า: "${question}"
ระบบเดาว่าน่าจะหมายถึง: ${guesses}

กติกาการตอบ:
1. ตอบภาษาไทย สุภาพ ลงท้าย "${HONORIFIC}" กระชับแต่ครบถ้วน ไม่เกิน 8 บรรทัด
2. ก่อนตอบ ให้ไตร่ตรองก่อนว่าลูกค้าต้องการรู้อะไรจริง ๆ แล้วจึงตอบให้ตรงที่สุด
3. ลูกค้ามักพิมพ์ผิด เช่น "พารา"/"ราคะ" = "ราคา", "สมัคเรียน" = "สมัครเรียน"
   ให้เดาเจตนาแล้วตอบไปเลย ห้ามตอบว่า "ไม่เข้าใจ" ถ้ายังพอเดาได้
4. เป้าหมายคือ "จบในข้อความเดียว" ลูกค้าไม่ต้องถามซ้ำและไม่ต้องรอทีมงานติดต่อกลับ
   ถ้าคำตอบกระจายอยู่หลายแถวในรายการข้างบน ให้รวบรวมมาตอบให้ครบในครั้งเดียว
5. ถ้าลูกค้าถามหลายเรื่องในข้อความเดียว ให้ตอบให้ครบทุกเรื่อง แยกเป็นบรรทัดละเรื่อง
6. ตอบเฉพาะสิ่งที่ถาม ไม่ต้องแถมข้อมูลที่ไม่เกี่ยวข้อง และไม่ต้องทวนคำถามยาว ๆ
7. ห้ามแต่งข้อมูลที่ไม่มีในข้างบน โดยเฉพาะราคา โปรโมชั่น หรือวันนัดหมาย
8. เฉพาะกรณีที่ข้อมูลข้างบนไม่มีคำตอบจริง ๆ หรือเป็นเรื่องที่ต้องตกลงรายบุคคล
   (ต่อรองราคา ออกใบเสนอราคา นัดหมายวันเวลา) จึงค่อยแจ้งเบอร์ 099-626-9787
   นอกเหนือจากนั้นให้ตอบเองให้จบ อย่าโยนให้ทีมงานโดยไม่จำเป็น
9. ห้ามใช้ Markdown เพราะ LINE แสดงผลไม่ได้ ใช้ข้อความธรรมดาและขึ้นบรรทัดใหม่
`;

  return {
    json: {
      replyToken: ev.replyToken,
      userId: (ev.source && ev.source.userId) || '',
      question,
      systemPrompt,
    },
  };
});

